function nearbyObject(x,y,dict,r=3){let best=null,bd=999;for(let yy=Math.max(0,y-r);yy<=Math.min(ROWS-1,y+r);yy++)for(let xx=Math.max(0,x-r);xx<=Math.min(COLS-1,x+r);xx++){const o=tile(xx,yy).object;if(dict[o]){const d=Math.abs(xx-x)+Math.abs(yy-y);if(d<bd){bd=d;best={x:xx,y:yy,o,def:dict[o]}}}}return best}
