function assignKeeper(s){let target=null,score=-1;for(const p of penCache){if(!p.animals.length||!gateWorkspot(p))continue;const hunger=p.animals.reduce((a,b)=>a+b.hunger,0)/p.animals.length;const sc=100-hunger;if(sc>score){score=sc;target=p}}if(target&&score>18){const spot=gateWorkspot(target),p=pathfind(s.x,s.y,spot[0],spot[1]);if(p.length){s.task={type:'feed',penId:target.id};s.path=p;s.status=`Walking to habitat ${target.id+1}`;return}}const r=randomAccessiblePath();s.path=pathfind(s.x,s.y,r[0],r[1]);s.task={type:'patrol'};s.status='Inspecting habitats'}
function assignJanitor(s){if(state.litter.length){let best=null,bd=999;for(const l of state.litter){const d=Math.abs(l.x-s.x)+Math.abs(l.y-s.y);if(d<bd&&accessiblePaths.has(key(l.x,l.y))){best=l;bd=d}}if(best){const p=pathfind(s.x,s.y,best.x,best.y);if(p.length||Math.floor(s.x)===best.x&&Math.floor(s.y)===best.y){s.task={type:'clean',x:best.x,y:best.y};s.path=p;s.status='Walking to litter';return}}}const r=randomAccessiblePath();s.path=pathfind(s.x,s.y,r[0],r[1]);s.task={type:'patrol'};s.status='Patrolling paths'}
function tourCandidates(){return[...viewingTargets(),...facilityTargets().filter(t=>EDUCATION[t.o])].sort(()=>Math.random()-.5)}
function startTour(s){const c=tourCandidates();if(c.length<2){s.cooldown=8;s.status='Waiting for tour stops';return}const first=c[0],p=pathfind(s.x,s.y,first.x,first.y);if(!p.length){s.cooldown=5;return}s.tourStops=c.slice(0,Math.min(5,c.length));s.task={type:'tour'};s.path=p;s.group=4+Math.floor(Math.random()*5);s.status=`Leading a group of ${s.group}`;earn(s.group*5,'tours');state.satisfaction=clamp(state.satisfaction+1.2,0,100)}
function advanceTour(s){s.tourStops.shift();state.education=clamp(state.education+1.2,0,100);state.reputation+=.5;if(!s.tourStops.length){s.task=null;s.group=0;s.cooldown=12+Math.random()*12;s.status='Tour complete';return}const t=s.tourStops[0],p=pathfind(s.x,s.y,t.x,t.y);if(p.length){s.path=p;s.status=`Tour stop: ${t.type==='view'?'animal habitat':OBJECTS[t.o]?.name||'education'}`}else advanceTour(s)}
function completeStaffTask(s){if(s.task?.type==='feed'){const p=penCache[s.task.penId];if(p)for(const a of p.animals)a.hunger=clamp(a.hunger+42,0,100);s.status='Food stations refilled'}else if(s.task?.type==='clean'){const l=state.litter.find(x=>x.x===s.task.x&&x.y===s.task.y);if(l){l.amount-=4;if(l.amount<=0)state.litter.splice(state.litter.indexOf(l),1)}s.status='Area cleaned'}s.task=null;s.workTimer=0}
